insert into sector_profiles (settore, version, status, pack, changelog)
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'Cos''è il tagliando?', $qrjc6dn$["cosa e il tagliando","cos e il tagliando","cosa comprende il tagliando","a cosa serve il tagliando","in cosa consiste il tagliando","cosa si fa nel tagliando"]$qrjc6dn$::jsonb, 'Il tagliando è la manutenzione periodica prevista dal costruttore: in genere comprende il cambio dell''olio e dei filtri e una serie di controlli sull''auto, con il programma indicato nel libretto di uso e manutenzione. Cosa viene fatto esattamente dipende dal modello e dai chilometri o dagli anni dell''auto.', $qq7autw${}$qq7autw$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'Ogni quanto si fa il tagliando?', $qe8nr6w$["ogni quanto si fa il tagliando","ogni quanto va fatto il tagliando","quando va fatto il tagliando","quando si fa il tagliando","ogni quanto devo fare il tagliando","come faccio a sapere quando fare il tagliando"]$qe8nr6w$::jsonb, 'La scadenza è indicata dal costruttore nel libretto di uso e manutenzione: di solito si considera il primo limite raggiunto tra chilometri percorsi e tempo trascorso dall''ultimo tagliando. Su alcune auto una spia sul cruscotto segnala la scadenza.', $qgy7gad${}$qgy7gad$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'Che differenza c''è tra tagliando e revisione?', $qncveh1$["differenza tra tagliando e revisione","differenza tra revisione e tagliando","tagliando e revisione sono la stessa cosa","il tagliando e la revisione sono uguali","che differenza c e tra tagliando e revisione"]$qncveh1$::jsonb, 'Sono due cose diverse: il tagliando è la manutenzione periodica per mantenere l''auto in buono stato, mentre la revisione è un controllo obbligatorio per legge che verifica sicurezza ed emissioni per poter circolare. Il tagliando non sostituisce la revisione e viceversa.', $qyk5ffz${}$qyk5ffz$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'Ogni quanto si fa la revisione?', $qf4qp3w$["ogni quanto si fa la revisione","ogni quanto va fatta la revisione","quando scade la revisione","quando devo fare la revisione","quando si fa la prima revisione","ogni quanto la revisione dell auto"]$qf4qp3w$::jsonb, 'Per le auto private la prima revisione si fa in genere dopo quattro anni dall''immatricolazione e poi ogni due anni. La scadenza precisa si legge sulla carta di circolazione o sul tagliando adesivo dell''ultima revisione.', $qspfpv9${}$qspfpv9$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'Cosa serve per fare la revisione?', $qarvzyz$["cosa serve per la revisione","che documenti servono per la revisione","cosa devo portare per la revisione","cosa serve per fare la revisione"]$qarvzyz$::jsonb, 'In genere serve la carta di circolazione dell''auto. Per eventuali altre indicazioni conviene verificare con l''officina prima di portare l''auto.', $qukj0cc${}$qukj0cc$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'Cos''è la pre-revisione?', $q2xvani$["cos e la pre revisione","cosa e la pre revisione","cosa significa pre revisione","a cosa serve la pre revisione","serve la pre revisione","cos e il controllo prima della revisione"]$q2xvani$::jsonb, 'La pre-revisione è un controllo che si fa prima della revisione ufficiale per verificare gli aspetti che di solito vengono esaminati, come freni, luci, pneumatici e emissioni, così da sistemare in anticipo eventuali problemi. Non è obbligatoria e non sostituisce la revisione.', $qnne4dt${}$qnne4dt$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'Cosa si controlla in un controllo generale dell''auto?', $q8aeihm$["cosa si controlla in un controllo generale","cosa controllate nel controllo dell auto","cosa comprende il controllo completo","cosa si controlla prima di un viaggio"]$q8aeihm$::jsonb, 'Un controllo generale riguarda di norma elementi come livelli dei liquidi, freni, luci, pneumatici, batteria e stato visibile di cinghie e componenti. L''elenco preciso dipende dall''officina e dall''auto.', $qc1sy9c${}$qc1sy9c$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'Ogni quanto si cambia l''olio motore?', $qu5soon$["ogni quanto si cambia l olio","ogni quanto va cambiato l olio","ogni quanto devo cambiare l olio","quando si cambia l olio","ogni quanto si fa il cambio olio"]$qu5soon$::jsonb, 'L''intervallo dipende dal motore, dal tipo di olio e da come si usa l''auto (molti tragitti brevi, città, autostrada): è indicato dal costruttore nel libretto di uso e manutenzione, e di solito il cambio olio si fa insieme al tagliando.', $qcgzmh0${}$qcgzmh0$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'Cosa significa la spia motore?', $qk99lew$["cosa significa la spia motore","cosa vuol dire la spia motore","a cosa serve la spia motore","cosa significa la spia del motore","cosa indica la spia motore","cos e la spia motore"]$qk99lew$::jsonb, 'La spia motore si accende quando la centralina rileva un''anomalia, che può avere cause molto diverse. Per capire quale serve una lettura con la strumentazione diagnostica e il parere del meccanico. Se la spia lampeggia o è rossa, o se l''auto si comporta in modo strano, è meglio non proseguire e contattare l''officina.', $q4u56c1${}$q4u56c1$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'Cosa significa la spia dell''olio?', $qykoemx$["cosa significa la spia dell olio","cosa vuol dire la spia dell olio","a cosa serve la spia dell olio","cosa indica la spia dell olio","cos e la spia dell olio"]$qykoemx$::jsonb, 'La spia dell''olio segnala un problema legato alla pressione o al livello dell''olio del motore. Se si accende in marcia è una situazione da non sottovalutare: conviene fermarsi appena possibile in sicurezza, non proseguire e contattare l''officina o il soccorso stradale.', $qvxfgzt${}$qvxfgzt$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'Cosa significa la spia dell''airbag?', $qdfdyft$["cosa significa la spia dell airbag","cosa vuol dire la spia airbag","a cosa serve la spia airbag","cosa indica la spia airbag","spia airbag accesa cosa significa"]$qdfdyft$::jsonb, 'La spia dell''airbag segnala che il sistema di sicurezza ha rilevato un''anomalia e potrebbe non funzionare correttamente in caso di incidente. Serve un controllo con strumentazione adatta da parte dell''officina.', $qiw9l0c${}$qiw9l0c$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'Cosa devo fare se si accende una spia in viaggio?', $qj198qe$["cosa devo fare se si accende una spia","cosa fare se si accende una spia","che significano i colori delle spie","spia rossa o gialla cosa cambia","si accende una spia cosa faccio"]$qj198qe$::jsonb, 'In genere le spie rosse indicano un problema importante: conviene accostare in sicurezza e non proseguire. Quelle gialle o arancioni segnalano un''anomalia da far controllare. Il significato di ogni spia è nel libretto di uso e manutenzione; per qualsiasi dubbio è meglio sentire l''officina.', $qkblrir${}$qkblrir$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'Cos''è la diagnosi con la centralina?', $q90g9xg$["cos e la diagnosi","a cosa serve la diagnosi","cos e la diagnosi con la centralina","come funziona la diagnosi elettronica","cosa e la diagnosi computerizzata","a cosa serve leggere la centralina"]$q90g9xg$::jsonb, 'La diagnosi elettronica consiste nel collegare uno strumento alla centralina dell''auto per leggere gli errori memorizzati. Serve a capire in quale area cercare il problema, ma l''interpretazione e le verifiche successive le fa il meccanico.', $qx4fs2f${}$qx4fs2f$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'Ogni quanto si cambiano le pastiglie dei freni?', $qj13d1z$["ogni quanto si cambiano le pastiglie","quando si cambiano le pastiglie dei freni","ogni quanto vanno cambiate le pastiglie","quando vanno cambiate le pastiglie","quando si cambiano i dischi dei freni"]$qj13d1z$::jsonb, 'Dipende molto dal tipo di guida, dal percorso e dal peso dell''auto, quindi non c''è una scadenza fissa. L''usura si verifica con un controllo in officina, che è il modo sicuro per sapere quando intervenire.', $qpkkcdv${}$qpkkcdv$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'Cos''è il liquido dei freni e va cambiato?', $q1xz04o$["cos e il liquido freni","va cambiato il liquido dei freni","ogni quanto si cambia il liquido dei freni","a cosa serve il liquido dei freni","il liquido freni scade"]$q1xz04o$::jsonb, 'Il liquido dei freni trasmette la forza del pedale all''impianto frenante e con il tempo assorbe umidità, perdendo efficacia. Per questo il costruttore ne prevede la sostituzione periodica, indicata nel libretto di uso e manutenzione.', $qrls8xu${}$qrls8xu$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'Ogni quanto si cambia la cinghia di distribuzione?', $qmt6cmc$["ogni quanto si cambia la cinghia di distribuzione","quando va cambiata la cinghia di distribuzione","ogni quanto va sostituita la distribuzione","quando si cambia la distribuzione","a cosa serve la cinghia di distribuzione"]$qmt6cmc$::jsonb, 'La distribuzione sincronizza i movimenti del motore e va sostituita secondo gli intervalli di chilometri o di anni indicati dal costruttore, che cambiano da modello a modello. Rispettare la scadenza è importante perché una rottura può danneggiare seriamente il motore.', $qz8zb0z${}$qz8zb0z$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'Ogni quanto si cambiano le candele?', $q2l0k7z$["ogni quanto si cambiano le candele","quando si cambiano le candele","a cosa servono le candele","ogni quanto vanno cambiate le candele","quando si cambia la batteria dell auto"]$q2l0k7z$::jsonb, 'Le candele (nei motori a benzina) vanno sostituite secondo il piano del costruttore, che dipende dal tipo di candela e di motore. Di solito il controllo e l''eventuale sostituzione rientrano nel tagliando.', $qdf7n2g${}$qdf7n2g$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'Quanto dura la batteria dell''auto?', $q8hpm5l$["quanto dura la batteria","quanto dura la batteria dell auto","ogni quanto si cambia la batteria","quando va cambiata la batteria","ogni quanto va sostituita la batteria"]$q8hpm5l$::jsonb, 'La durata della batteria dipende dall''uso (tragitti brevi, freddo, accessori accesi) e dall''età. Un controllo in officina permette di verificare lo stato di carica e di salute prima che l''auto non parta.', $qo2nrs0${}$qo2nrs0$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'A cosa serve la ricarica del clima?', $qtipbfs$["a cosa serve la ricarica del clima","ogni quanto si ricarica il clima","ogni quanto si ricarica l aria condizionata","perche il clima non raffredda piu","cos e la sanificazione del clima","quando si ricarica il clima"]$qtipbfs$::jsonb, 'Con il tempo l''impianto di climatizzazione può perdere efficienza e l''abitacolo può avere cattivi odori: un controllo periodico, con ricarica o sanificazione quando necessarie, aiuta a mantenerlo efficiente. Se il clima non raffredda, serve un controllo per capirne la causa.', $qxrnzvs${}$qxrnzvs$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'Cos''è l''equilibratura e la convergenza?', $qekmzc0$["cos e la convergenza","cos e l equilibratura","a cosa serve l equilibratura","a cosa serve la convergenza","cos e l assetto","cosa significa convergenza"]$qekmzc0$::jsonb, 'L''equilibratura bilancia le ruote per evitare vibrazioni al volante; la convergenza (o assetto) regola l''allineamento delle ruote per una guida stabile e un consumo uniforme degli pneumatici. Se l''auto tira da un lato o il volante vibra, serve un controllo in officina.', $q5yl07l${}$q5yl07l$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'Quando vanno cambiate le gomme?', $qox12t8$["quando si cambiano le gomme","ogni quanto si cambiano le gomme","quando si montano le gomme invernali","gomme invernali obbligatorie","quando cambiare i pneumatici"]$qox12t8$::jsonb, 'Le gomme vanno sostituite quando il battistrada è consumato oltre il limite di legge o quando sono danneggiate o invecchiate; un controllo in officina o dal gommista lo verifica. In alcuni periodi dell''anno e su certe strade è previsto l''obbligo di pneumatici invernali o catene a bordo: i periodi sono indicati dalla segnaletica o dalle ordinanze.', $qqvv16h${}$qqvv16h$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'A cosa servono gli ammortizzatori?', $qon1q5d$["a cosa servono gli ammortizzatori","quando si cambiano gli ammortizzatori","ogni quanto si cambiano gli ammortizzatori","cosa fanno gli ammortizzatori"]$qon1q5d$::jsonb, 'Gli ammortizzatori mantengono le ruote a contatto con la strada e contribuiscono a stabilità e frenata. Si usurano nel tempo: se l''auto rimbalza o balla in curva, serve un controllo in officina.', $qztj7xn${}$qztj7xn$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'Cos''è il FAP o filtro antiparticolato?', $qnsj6t9$["cos e il fap","cos e il filtro antiparticolato","a cosa serve il fap","cosa e il dpf","cos e il dpf","che cos e il fap"]$qnsj6t9$::jsonb, 'Il filtro antiparticolato (FAP o DPF) è presente su molte auto diesel e trattiene le particelle inquinanti dei gas di scarico, per poi bruciarle durante la rigenerazione. Se una spia lo segnala serve un controllo in officina: non va rimosso, è parte dell''impianto di scarico omologato.', $qgqj7kd${}$qgqj7kd$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'Si fa il tagliando anche sulle auto ibride o elettriche?', $qna9zmp$["si fa il tagliando anche sulle ibride","serve il tagliando sulle auto elettriche","tagliando auto ibrida","tagliando auto elettrica","le auto elettriche hanno il tagliando"]$qna9zmp$::jsonb, 'Sì, anche le auto ibride ed elettriche hanno una manutenzione programmata dal costruttore, con controlli su freni, sospensioni, pneumatici e sistemi specifici. Se un''officina sia attrezzata per questi veicoli lo può dire solo l''officina stessa.', $qrszu01${}$qrszu01$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'Se faccio il tagliando fuori dalla casa madre perdo la garanzia?', $qxv2fux$["perdo la garanzia se faccio il tagliando fuori dalla casa","tagliando in officina indipendente garanzia","il tagliando fuori concessionaria fa decadere la garanzia","garanzia e tagliando in officina","posso fare il tagliando in una officina non ufficiale"]$qxv2fux$::jsonb, 'In genere la garanzia del costruttore non decade solo perché la manutenzione è eseguita in un''officina indipendente, se si rispettano il piano del costruttore e ricambi adeguati. Per il suo caso specifico conviene verificare le condizioni scritte nel contratto di garanzia.', $qv7bd5w${}$qv7bd5w$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'Che informazioni servono per un preventivo?', $qno3o8u$["che informazioni servono per un preventivo","cosa serve per un preventivo","cosa devo dirvi per il preventivo","cosa vi serve per fare un preventivo","cosa serve sapere per il preventivo"]$qno3o8u$::jsonb, 'Per preparare un preventivo all''officina servono di solito marca, modello, anno, alimentazione e chilometri dell''auto, la targa e una descrizione chiara del lavoro o del problema. Il preventivo definitivo lo formula l''officina, spesso dopo aver visto l''auto.', $qr23cln${}$qr23cln$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('autofficina', 1, 'production', 'info_interventi', 'Quanto tempo ci vuole per un intervento?', $qkdhfjr$["quanto tempo ci vuole per un tagliando","quanto dura il tagliando","quanto ci vuole per la revisione","quanto tempo ci vuole per la riparazione","in quanto tempo si fa un intervento","quanto tempo serve per la riparazione"]$qkdhfjr$::jsonb, 'I tempi dipendono dal tipo di intervento, dal modello dell''auto, dalla disponibilità dei ricambi e dal carico di lavoro dell''officina, quindi non è possibile indicarli in modo generale. L''officina può darle un''indicazione concreta una volta definito il lavoro.', $q81o13i${}$q81o13i$::jsonb);
insert into sector_test_scenarios (settore, codice, categoria, scenario) values ('autofficina', 'AU01', 'BOOKING', $qah9x1v${"scenario":{"input":"Buongiorno, vorrei prenotare un tagliando","expected":{"intent":"prenota_intervento","entities":{"servizio":"tagliando"},"action":"ask_missing_information","next_question":"nome_cliente","safety":"LOW"},"tenant":{"campi":["nome_cliente","sintomo"],"haCalendario":true,"info_generali":{"indirizzo":"via dei Test 10","prezzi_note":"tagliando base 120 euro, cambio olio e filtri 90 euro","orari_note":"lun-ven 8:30-18:30, sabato 8:30-12:30","altre_informazioni":"parcheggio interno, auto sostitutiva su prenotazione"}}}}$qah9x1v$::jsonb) on conflict (settore, codice) do update set categoria = excluded.categoria, scenario = excluded.scenario;
