insert into sector_test_scenarios (settore, codice, categoria, scenario) values ('autofficina', 'AU03', 'BOOKING', $qm57us3${"scenario":{"input":"Vorrei un appuntamento","expected":{"intent":"prenota_intervento","action":"ask_missing_information","next_question":"servizio"},"tenant":{"campi":["nome_cliente","sintomo"],"haCalendario":true,"info_generali":{"indirizzo":"via dei Test 10","prezzi_note":"tagliando base 120 euro, cambio olio e filtri 90 euro","orari_note":"lun-ven 8:30-18:30, sabato 8:30-12:30","altre_informazioni":"parcheggio interno, auto sostitutiva su prenotazione"}}}}$qm57us3$::jsonb) on conflict (settore, codice) do update set categoria = excluded.categoria, scenario = excluded.scenario;
insert into sector_test_scenarios (settore, codice, categoria, scenario) values ('autofficina', 'AU04', 'BOOKING', $qsgd4i8${"scenario":{"input":"avete posto domani mattina?","expected":{"intent":"prenota_intervento","entities":{"giorno":"domani","fascia_oraria":"mattina"},"action":"ask_missing_information","next_question":"servizio"},"tenant":{"campi":["nome_cliente","sintomo"],"haCalendario":true,"info_generali":{"indirizzo":"via dei Test 10","prezzi_note":"tagliando base 120 euro, cambio olio e filtri 90 euro","orari_note":"lun-ven 8:30-18:30, sabato 8:30-12:30","altre_informazioni":"parcheggio interno, auto sostitutiva su prenotazione"}}}}$qsgd4i8$::jsonb) on conflict (settore, codice) do update set categoria = excluded.categoria, scenario = excluded.scenario;
